INSERT INTO crawl_data (id, crawl_result_id, site_id, agent_type, items, store_info, item_count, created_at) VALUES (23, 56, 8, 'news', '[{"url": "https://www.sedaily.com/article/20047780?ref=naver", "date": "1시간 전", "press": "서울경제", "title": "“한때 꿈의 휴양지였는데 텅텅 비었다”…1년 새 관광객 ‘반토막’ 난...", "article_id": 1, "description": "우크라이나·가자지구·이란 등에서 가시적 성과를 내지 못한 상황에서 쿠바 체제를 흔들어 정치적 실적을 쌓으려 한다는 해석이 뒤따른다. 한국 여성 해외여행 세계 1위의 비극... 스페인 장관이 “지금 당장 표 사라”고 경고한 진짜 이유", "display_order": 1, "search_keyword": "해외여행"}, {"url": "http://www.newsprime.co.kr/news/article.html?no=734505", "date": "1시간 전", "press": "파이낸셜뉴스", "title": "[발행인 칼럼] ''공항 포퓰리즘'' 늪에 빠진 ''대한민국''", "article_id": 2, "description": "정작 해외여행을 위해 미국이나 유럽에 도착한 뒤에는 몇 시간씩 기차를 타고 이동하거나 자동차로 장거리를 이동하는 것에 별다른 불만을 제기하지 않는다. 미국 LA공항에 내려 4~5시간을 운전해 다른 도시로 이동하고, 프랑크푸르트에 내려 독일 남부로 철도를 타고 이동하는 것은 자연스럽게 받아들인다....", "display_order": 2, "search_keyword": "해외여행"}, {"url": "http://www.fnnews.com/news/202605241816397809", "date": "3시간 전", "press": "스포츠경향", "title": "고열에 수학여행 당일 참가 취소, 전액 환불 될까[소비의 정석]", "article_id": 3, "description": "24일 한국소비자원에 따르면 코로나 19 팬데믹 이후 해외여행 수요가 급격히 늘어나면서, 여행 전 갑작스러운 사고나 질병 발생으로 인한 소비자 분쟁 사례도 늘어나고 있다. 일반적으로 여행 출발 직전이나 당일 취소의 경우 높은 위약금이 발생하는 사례가 많다. 다만, A씨 사례는 여행사의 약관 내용이...", "display_order": 3, "search_keyword": "해외여행"}, {"url": "http://www.knpnews.com/news/articleView.html?idxno=33772", "date": "3시간 전", "press": "OSEN", "title": "''중동이 건넨 말들'' - 2026년 상반기 청소년 우수 교양도서 선정", "article_id": 4, "description": "그리고 중동 여행을 처음 준비하는 여행가나 해외 사업을 준비하는 사업가들에게 ''중동의 길잡이''로 좋은 역할을 할 것으로 보인다. 백정순 저자는 \"이 책은 전문가처럼 방대한 지식을 담거나, 가진 건 아니지만 직접 부딪히며 익힌 중동의 진짜 얼굴을 전하는데 힘을 쏟았다\"며 \"낯선 땅에서 사람들과의 만남...", "display_order": 4, "search_keyword": "해외여행"}, {"url": "https://sports.khan.co.kr/article/202605241640013?pt=nv", "date": "5시간 전", "press": "동아일보", "title": "강동원, 음악방송 공약 질색…“혹시 천만 되면 어떡해요?” (핑계고)", "article_id": 5, "description": "이날 출연진은 해외여행 예능 이야기를 나누던 중 함께 프로그램해보자는 분위기로 이어졌다. 이에 박지현은 “이렇게 한번 같이 가볼까요?”라고 제안했고, 강동원은 곧바로 “왜 자꾸 뭘 같이 하자고 하냐”며 손사래를 쳤다. 이를 지켜보던 신하균은 “박지현 씨가 음악방송도 하고 싶어 한다”고 폭로했고...", "display_order": 5, "search_keyword": "해외여행"}, {"url": "http://www.osen.co.kr/article/G1112807688", "date": "5시간 전", "press": "경향신문", "title": "강동원, 박지현 ‘천만공약’ 음방 제안 거절..“혹시 되면 어떡하냐”...", "article_id": 6, "description": "이날 박지현은 해외여행 예능에 대한 이야기가 나오자 “이렇게 한 번 갈까요?”라고 운을 뗐고, 강동원은 “왜 이래. 계속 뭘 하재 같이”라고 고발했다. 신하균은 “그렇게 음악방송을 하고 싶어 해요”라고 했고, 박지현은 “음악방송 하면 좋잖아요. 저희 안 그래도 트라이앵글인데”라고 속내를 밝혔다....", "display_order": 6, "search_keyword": "해외여행"}, {"url": "https://www.donga.com/news/Culture/article/all/20260524/133982094/1", "date": "6시간 전", "press": "한국경제", "title": "유류할증료 폭탄에 국내로 눈 돌린 여행객…숙박 예약 150% 급증", "article_id": 7, "description": "이가희 여기어때 홍보팀장은 “중동 정세 등으로 인해 해외여행 비용이 크게 늘어나면서 가격 부담이 상대적으로 덜한 지역으로 몰린 것으로 보인다”며 “국내 숙박의 경우 특정 일자가 가까워질수록 예약이 높아지는 경향이 있어서 7월 말 8월 초의 예약도 늘어날 가능성이 있다”고 분석했다. 최근 정부가...", "display_order": 7, "search_keyword": "해외여행"}, {"url": "https://www.khan.co.kr/article/202605241522001", "date": "6시간 전", "press": "코메디닷컴", "title": "“값비싼 해외 대신 국내 여행하자”…울릉도·지역축제 상품 인기", "article_id": 8, "description": "중동전쟁 여파로 국제선 유류할증료가 한 때 33단계 최고 수준까지 치솟고 원·달러 환율마저 고공행진하는 등 해외여행 비용 부담이 커졌기 때문이다. 하나투어는 지역 축제와 체험형 콘텐츠를 연계한 상품 확대에 나서고 있다. 오는 6월 현충일 연휴를 맞아 전북 익산 근대역사문화축전과 미륵사지 등을 연계한...", "display_order": 8, "search_keyword": "해외여행"}, {"url": "https://www.ebn.co.kr/news/articleView.html?idxno=1709971", "date": "6시간 전", "press": "JIBS", "title": "방한객 202만명 기록...코로나 이전 대비 124% ''쑥↑''", "article_id": 9, "description": "9% 증가했다. 한편 국민 해외여행 수요도 빠르게 회복되고 있다. 지난달 해외로 출국한 국민은 228만5843명으로 전년 대비 6.3% 증가했으며, 2019년 4월과 비교해도 101.8% 수준을 기록했다. 1~4월 누적 해외여행객 역시 1062만 명으로, 코로나19 이전 대비 105% 수준까지 회복됐다.", "display_order": 9, "search_keyword": "해외여행"}, {"url": "https://www.hankyung.com/article/2026052232337", "date": "6시간 전", "press": "서울경제", "title": "MBC 퇴사 후 ''월 1000만'' 수입…김민식 \"난 생활체육인\" [본캐부캐]", "article_id": 10, "description": "일은 홀수 달에만, 짝수 달에는 해외로 여행을 떠난다. 이미 6월 스페인, 8월 캐나다 여행을 예약해 뒀다. 그러면서도 다음 책 집필을 이미 시작했다고 했다. 영어 공부부터 글쓰기, 인간관