INSERT INTO crawl_data (id, crawl_result_id, site_id, agent_type, items, store_info, item_count, created_at) VALUES (30, 85, 8, 'news', '[{"url": "http://www.globalepic.co.kr/view.php?ud=20260526110750906048439a4874_29", "date": "1분 전", "press": "파이낸셜뉴스", "title": "항공 대신 배편으로...웹투어, 대마도 여행 수요 증가에 서비스 강화", "article_id": 1, "description": "웹투어(대표 홍성원)가 고유가 시대 새로운 해외여행 대안으로 떠오른 일본 배편 여행 수요 확대에 맞춰 대마도 여행상품과 실시간 선박 예약 서비스를 강화하고 있다. 항공 유류할증료 부담이 커지면서 비용 효율적인 선박 여행을 택하는 소비자가 늘고 있다. 그중 부산에서 고속페리로 2시간이면 닿는 대마도는...", "display_order": 1, "search_keyword": "해외여행"}, {"url": "http://www.fnnews.com/news/202605261042268222", "date": "1분 전", "press": "파이낸셜뉴스", "title": "미디어경영학회 \"기업 메시지 시장, 도달보다 신뢰\"", "article_id": 2, "description": "연구는 생필품·디저트 같은 저관여 상품부터 해외여행·금융상품처럼 이용자의 정보 탐색과 판단이 중요한 고관여 상품까지 다양한 광고 유형을 대상으로 진행됐다. 연구 결과, 브랜드 메시지와 SMS는 동일한 이용자 니즈를 두고 경쟁하는 기업 메시지 서비스로 나타났다. 특히 브랜드 메시지는 신뢰성과 편의성...", "display_order": 2, "search_keyword": "해외여행"}, {"url": "http://www.fnnews.com/news/202605261038500635", "date": "27분 전", "press": "이데일리", "title": "\"10층 돌계단 아래 쿵..\" 80대 캐나다관광객 온병원서 수술 ''위기 모면''", "article_id": 3, "description": "크루즈선을 타고 일본과 한국 등 동남아 여행 중인 로슨 씨의 경우 다행히 출국 전 ''해외여행자 보험''에 가입해 두었던 것이 신의 한 수가 됐다. 현장 조율을 통해 캐나다 현지 보험회사로부터 온병원으로 직접 ''진료비 지불보증서''가 발송됐고, 환자는 거액의 병원비 부담 없이 치료에만 전념할 수 있게 됐다....", "display_order": 3, "search_keyword": "해외여행"}, {"url": "http://www.kdfnews.com/news/articleView.html?idxno=183557", "date": "27분 전", "press": "SBS", "title": "여행업계, 취향 따라 떠난다…\"소도시∙휴양∙도심 여행 세분화\"", "article_id": 4, "description": "사진=노랑풍선 해외여행 상품은 여행 목적에 따라 휴양형과 관광형으로 나뉘고 있다. 노랑풍선은 괌 PIC 리조트 중심의 올인클루시브 상품과 미국 서부 핵심 도시 및 국립공원을 둘러보는 장거리 패키지를 동시에 선보였다. 가족 단위 휴양 수요와 한 번에 다양한 여행지를 경험하려는 장거리 여행 수요를 함께...", "display_order": 4, "search_keyword": "해외여행"}, {"url": "http://www.economytalk.kr/news/articleView.html?idxno=421546", "date": "28분 전", "press": "스타뉴스", "title": "[캐시워크 돈버는퀴즈 종합]\"모스아웃,픽스 선풍기, CJ더마켓,국민건강...", "article_id": 5, "description": "특히 110V를 지원해 OO FREE기능으로 해외 여행 갈 때도 사용할 수 있습니다. (초성힌트 : ㅈㅇ)\"다. 정답은 ''전압''이다. 두번째 문제는 \"가열/ 보온/ 찜기 3in1 설계의 코릭 접이식 멀티쿠커는 8cm의 접이식이라 휴대가 간편하고 1.8L의 대용량입니다. 특히 강력한 내구성의 OOOOO 316L는 부식에 강하며, 염분이 많은...", "display_order": 5, "search_keyword": "해외여행"}, {"url": "https://www.slist.kr/news/articleView.html?idxno=741272", "date": "28분 전", "press": "SBS", "title": "[여행·관광] 모두투어 몽골 기획전부터 노랑풍선 괌·미국 서부 패키지", "article_id": 6, "description": "여행업계가 몽골 자연 체험형 기획전과 괌·미서부 라이브 상품 등을 통해 여름 휴가와 하반기 해외여행 수요를 공략하고 있다. 모두투어는 여름 이색 자연 여행지로 주목받는 몽골 상품 선택지를 확대한 ''여름 버킷리스트 몽골'' 기획전을 출시했다. 사진=모두투어 이번 기획전은 초원, 미니사막, 게르 숙박...", "display_order": 6, "search_keyword": "해외여행"}, {"url": "https://www.kbsm.net/news/view.php?idx=520661", "date": "35분 전", "press": "이코노미스트", "title": "OK웨딩 주최 ''2026 대구웨딩박람회'', 6월 6~7일 엑스코인터불고호텔서 개...", "article_id": 7, "description": "인증된 여행사와 연계해 다양한 해외 신혼여행 상품을 소개하며, 2027년 예식을 준비하는 예비부부에게는 사전 예약 시 올해 특가 수준의 상품을 적용하는 프로모션도 마련됐다. 허니문 계약 고객에게는 여행자 보험과 여행용 가방 증정 혜택이 제공될 예정이다.혼수 준비를 위한 특별 혜택도 준비됐다. 예복...", "display_order": 7, "search_keyword": "해외여행"}, {"url": "https://www.shinailbo.co.kr/news/articleView.html?idxno=5024118", "date": "35분 전", "press": "", "title": "은평구, 해외유입 홍역 증가에 예방수칙 준수 당부", "article_id": 8, "description": "은평구는 최근 해외여행을 통한 홍역 국내 유입 사례가 이어지고 있다며 예방백신 접종 여부 확인과 개인위생 관리 등에 각별한 주의가 필요하다고 26일 밝혔다. 질병관리청에 따르면 현재 국내 홍역 환자 대부분은 해외유입 관련 사례로 확인되고 있다. 특히 동남아시아와 유럽, 미주 일부 국가를 중심으로 홍역...", "display_order": 8, "search_keyword": "해외여행"}, {"url": "https://www.discoverynews.kr/news/articleView.html?idxno=1091937", "date": "1시간 전", "press": "", "title": "노랑풍선, 여름 휴가철 맞아 괌·미서부 여행 상품 라인업 강화", "article_id": 9, "description": "괌 PIC [사진=노랑풍선]  최근 해외여행 시장에서 여행객들의 목적이 ''휴식 위주의 단거리 휴양''과 ''관광 중심의 장거리 투어''로 뚜렷하게 나뉘고 있다. 이에 따라 여행사들은 고객의 여행 스타일을 반영한 상품 포트폴리오를 구성하고 있다. 노랑풍선은 이러한 시장 흐름에 발맞춰 오는 5월 27일과 28일 양일간...", "display_order": 9, "search_keyword": "해외여행"}, {"url": "https://www.dnews.co.kr/uhtml/view.jsp?idxno=202605251014228270843", "date": "1시간 전", "press": "", "title": "진주시, 베이징 경남관광 로드쇼 참가...‘관광 홍보·세일즈’ 펼쳐", "article_id": 10, "description": "개발과 해외 온라인 여행사(OTA)와의 연계 홍보 등을 지속적으로 추진할 계획”이라고 밝혔다. 또한 진주성, 진주남강유등전시관, 남강 유람선 ‘김시민호’, 진주대첩 역사공원, 중앙시장, 진주냉면 등 진주 고유의 역사·미식·야간 관광자원을 연계한 체류형 관광코스를 함께 소개했다. 아울러 행사장에...", "display_order": 10, "search_keyword": "해외여행"}]', '{"site_name": "네이버뉴스검색"}', 10, '2026-05-26T11:11:55');
