INSERT INTO crawl_data (id, crawl_result_id, site_id, agent_type, items, store_info, item_count, created_at) VALUES (32, 78, 8, 'news', '[{"url": "https://news.sbs.co.kr/news/endPage.do?news_id=N1008578197&plink=ORI&cooper=NAVER", "date": "6분 전", "press": "SBS", "title": "\"자리 없어요\" 망연자실…제주 덮친 위기", "article_id": 1, "description": "여름 성수기, 해외여행도 좋지만 제주도로 향하는 분들 참 많으시죠. 하지만 제주 노선의 좌석 부족 문제가 현실화하고 있습니다. 제주도관광협회에 따르면 올해 하계 스케줄 기준 제주공항 하루 평균 공급 좌석은 지난해보다 1009석이 줄었습니다. 대한항공과 아시아나항공 합병으로 제주 노선 13개 슬롯이...", "display_order": 1, "search_keyword": "해외여행"}, {"url": "http://www.economytalk.kr/news/articleView.html?idxno=421537", "date": "6분 전", "press": "이코노미스트", "title": "[캐시워크 돈버는퀴즈 종합]\"모스아웃,픽스 선풍기, CJ더마켓,국민건강...", "article_id": 2, "description": "특히 110V를 지원해 OO FREE기능으로 해외 여행 갈 때도 사용할 수 있습니다. (초성힌트 : ㅈㅇ)\"다. 정답은 ''전압''이다. 두번째 문제는 \"가열/ 보온/ 찜기 3in1 설계의 코릭 접이식 멀티쿠커는 8cm의 접이식이라 휴대가 간편하고 1.8L의 대용량입니다. 특히 강력한 내구성의 OOOOO 316L는 부식에 강하며, 염분이 많은...", "display_order": 2, "search_keyword": "해외여행"}, {"url": "https://economist.co.kr/article/view/ecn202605200018", "date": "22분 전", "press": "동아일보", "title": "136개월 만의 흑자 골든타임…‘지방’ 못가면 도로아미타불 [K관광 ‘서...", "article_id": 3, "description": "중동 지역의 전쟁 확산 우려가 최고조에 달하자, 불안감을 느낀 내국인 해외여행 예정자들이 대거 발길을 돌렸다. 이들이 선택한 대안은 국내 지방 여행지였다. 실제로 마이리얼트립 내부 데이터 기준, 2026년 1분기(1~3월) 국내 숙소 검색량은 전년 동기 대비 약 20% 증가했다. 결제액 또한 증가하며 특히 연초...", "display_order": 3, "search_keyword": "해외여행"}, {"url": "https://daily.hankooki.com/news/articleView.html?idxno=1367136", "date": "22분 전", "press": "주간조선", "title": "[창간기획·멕시코 크루즈②] \"매일 아침 눈뜨면 다른 도시\"…바다 위 영...", "article_id": 4, "description": "비용과 언어의 장벽이 낮아지고 있는 지금, 크루즈는 이제 국내여행과 해외여행의 경계를 넘어선 또 하나의 새로운 여행 선택지로 자리 잡고 있다. 바다 위 호텔에서 맞이하는 느긋한 아침은 우리의 새로운 여행 문화가 될 것이라고 감히 예상해 본다. 태평양으로 지는 노을 바라보며 여행객이 사진을 찍고 있다....", "display_order": 4, "search_keyword": "해외여행"}, {"url": "https://www.g-enews.com/view.php?ud=2026052516152943330c8c1c064d_1", "date": "1시간 전", "press": "국민일보", "title": "“버틸 시간은 98일뿐”… 글로벌 석유 재고, 호르무즈 봉쇄에 ‘마지노...", "article_id": 5, "description": "아시아 중심 54개국 ‘강제 절전·해외여행 자제’령… 일본은 보조금 딜레마 원유 공급 회복이 지연되면서 전 세계 에너지 안보는 이제 ‘공급 확대’가 아닌 치욕적인 ‘수요 억제’ 단계로 진입했다. IEA 통계에 따르면 현재 전 세계 54개 국가 및 지역 정부가 긴급 에너지 절약 조치를 공표하고 발효했다....", "display_order": 5, "search_keyword": "해외여행"}, {"url": "https://www.donga.com/news/Society/article/all/20260526/133989236/2", "date": "1시간 전", "press": "중앙일보", "title": "“싸고 힙해요” 2030 핫플된 동묘… 검색량 성수-연남 넘어섰다", "article_id": 6, "description": "젊은층은 공공기관이 운영하는 무료 프로그램에 참여하거나, 해외 대신 국내 여행을 택하는 등 소비를 줄이고 있다. 3년 차 회사원 김솔희 씨(27)는 최근 큰 프로젝트를 마치고 전북 전주시로 휴가를 떠나기로 했다. 김 씨는 “원래 1년에 4, 5번 해외로 나갔는데, 유류할증료가 올라서 국내로 틀었다”고 했다....", "display_order": 6, "search_keyword": "해외여행"}, {"url": "http://weekly.chosun.com/news/articleView.html?idxno=51820", "date": "1시간 전", "press": "동아일보", "title": "놀이공원 ''매직패스'' 논란과 불공정 권하는 사회 [이완의 생활형 진보주...", "article_id": 7, "description": "무리하게 빚을 내서라도 명품을 사고, 해외 여행을 가는 식으로 지위를 꾸민다. 많은 사람이 자녀 적성이나 수준과 맞지 않게 일단 학원에 보내는 것도 같은 맥락에서 나오는 행동으로 보인다. \"어머니가 체감하는 사회 불평등 수준이 전보다 불평등한 방향으로 변화했다고 인식한 경우 중학교 이후의 자녀에 대한...", "display_order": 7, "search_keyword": "해외여행"}, {"url": "https://www.megaeconomy.co.kr/news/newsview.php?ncode=1065546581006598", "date": "1시간 전", "press": "스포츠경향", "title": "[경제돋보기] 1500원 돌파한 환율, 내 지갑과 아파트값을 위협하는 진짜...", "article_id": 8, "description": "단순히 해외여행 경비가 오르는 수준의 문제가 아니다. 이는 장바구니 물가 폭등, 서민들의 대출 이자 부담 가중, 나아가 아파트 건설 현장의 연쇄 부도 위기까지 단번에 연결되는 거대한 경제적 시한폭탄의 뇌관이다. 환율이 이토록 치솟은 근본적인 원인은 한미 양국 간의 ''돈 풀기'' 방식이 완전히 엇갈렸기...", "display_order": 8, "search_keyword": "해외여행"}, {"url": "https://www.kmib.co.kr/article/view.asp?arcid=1779707375&code=11151100&cp=nv", "date": "1시간 전", "press": "헤럴드경제", "title": "日로 ‘마운자로 원정’… 영상통화로 진료받고 호텔서 약 받는다", "article_id": 9, "description": "해외 직구와 원정 구매가 잇따르자 지난해 식약처는 비만치료제를 ‘유해 통보’ 대상으로 포함해 해외 배송과 여행자 휴대 반입 관리를 강화했다. 여행자 휴대 반입이나 직구는 어렵고, 예외적으로 허용되는 상황에도 의료기관 진단서를 첨부해 관할 시·도 또는 한국희귀필수의약품센터에...", "display_order": 9, "search_keyword": "해외여행"}, {"url": "https://www.traveltimes.co.kr/news/articleView.html?idxno=415843", "date": "1시간 전", "press": "", "title": "[커버스토리] 지방분산 드라이브 속 현장의 목소리 \"공항·디지털·유통...", "article_id": 10, "description": "전주관광재단은 \"지역이 체험 상품을 기획하는 것까지는 가능하지만, 해외 여행업계와의 연계와 글로벌 유통망 확보는 정부 지원 없이는 한계가 있다\"고 밝혔다. 재단 측은 글로벌 OTA 입점 지원, 해외 여행업계와의 B2B 연계 창구 마련, 외국인이 자국 앱으로 예약·결제·이동 수단 호출을 한 번에 해결할 수 있는...", "display_order": 10, "search_keyword": "해외여행"}]', '{"site_name": "네이버뉴스검색"}', 10, '2026-05-26T07:24:55');
