INSERT INTO crawl_data (id, crawl_result_id, site_id, agent_type, items, store_info, item_count, created_at) VALUES (38, 55, 8, 'news', '[{"url": "https://www.sedaily.com/article/20047780?ref=naver", "date": "1시간 전", "press": "서울경제", "title": "“한때 꿈의 휴양지였는데 텅텅 비었다”…1년 새 관광객 ‘반토막’ 난...", "article_id": 1, "description": "우크라이나·가자지구·이란 등에서 가시적 성과를 내지 못한 상황에서 쿠바 체제를 흔들어 정치적 실적을 쌓으려 한다는 해석이 뒤따른다. 한국 여성 해외여행 세계 1위의 비극... 스페인 장관이 “지금 당장 표 사라”고 경고한 진짜 이유", "display_order": 1, "search_keyword": "해외여행"}, {"url": "http://www.newsprime.co.kr/news/article.html?no=734505", "date": "1시간 전", "press": "파이낸셜뉴스", "title": "[발행인 칼럼] ''공항 포퓰리즘'' 늪에 빠진 ''대한민국''", "article_id": 2, "description": "정작 해외여행을 위해 미국이나 유럽에 도착한 뒤에는 몇 시간씩 기차를 타고 이동하거나 자동차로 장거리를 이동하는 것에 별다른 불만을 제기하지 않는다. 미국 LA공항에 내려 4~5시간을 운전해 다른 도시로 이동하고, 프랑크푸르트에 내려 독일 남부로 철도를 타고 이동하는 것은 자연스럽게 받아들인다....", "display_order": 2, "search_keyword": "해외여행"}, {"url": "http://www.fnnews.com/news/202605241816397809", "date": "3시간 전", "press": "스포츠경향", "title": "고열에 수학여행 당일 참가 취소, 전액 환불 될까[소비의 정석]", "article_id": 3, "description": "24일 한국소비자원에 따르면 코로나 19 팬데믹 이후 해외여행 수요가 급격히 늘어나면서, 여행 전 갑작스러운 사고나 질병 발생으로 인한 소비자 분쟁 사례도 늘어나고 있다. 일반적으로 여행 출발 직전이나 당일 취소의 경우 높은 위약금이 발생하는 사례가 많다. 다만, A씨 사례는 여행사의 약관 내용이...", "display_order": 3, "search_keyword": "해외여행"}, {"url": "http://www.knpnews.com/news/articleView.html?idxno=33772", "date": "3시간 전", "press": "OSEN", "title": "''중동이 건넨 말들'' - 2026년 상반기 청소년 우수 교양도서 선정", "article_id": 4, "description": "그리고 중동 여행을 처음 준비하는 여행가나 해외 사업을 준비하는 사업가들에게 ''중동의 길잡이''로 좋은 역할을 할 것으로 보인다. 백정순 저자는 \"이 책은 전문가처럼 방대한 지식을 담거나, 가진 건 아니지만 직접 부딪히며 익힌 중동의 진짜 얼굴을 전하는데 힘을 쏟았다\"며 \"낯선 땅에서 사람들과의 만남...", "display_order": 4, "search_keyword": "해외여행"}, {"url": "https://sports.khan.co.kr/article/202605241640013?pt=nv", "date": "5시간 전", "press": "동아일보", "title": "강동원, 음악방송 공약 질색…“혹시 천만 되면 어떡해요?” (핑계고)", "article_id": 5, "description": "이날 출연진은 해외여행 예능 이야기를 나누던 중 함께 프로그램해보자는 분위기로 이어졌다. 이에 박지현은 “이렇게 한번 같이 가볼까요?”라고 제안했고, 강동원은 곧바로 “왜 자꾸 뭘 같이 하자고 하